package main

import (
	"fmt"
	"go/types"
	"golang.org/x/tools/go/packages"
	"os"
	"sort"
)

func main() {
	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedTypes | packages.NeedImports,
	}
	pkgs, err := packages.Load(cfg,
		"bufio", "bytes", "compress/flate", "compress/gzip", "compress/zlib",
		"crypto/cipher", "crypto/rand", "crypto/tls", "database/sql",
		"encoding/asn1", "encoding/base64", "encoding/binary", "encoding/csv",
		"encoding/gob", "encoding/json", "encoding/pem", "encoding/xml",
		"fmt", "hash", "html/template", "io", "log", "math/rand", "mime/multipart",
		"net", "net/http", "net/smtp", "net/url", "os", "os/exec", "path/filepath",
		"regexp", "strings", "text/template", "time",
	)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Load error: %v\n", err)
		return
	}

	for _, pkg := range pkgs {
		if pkg.Types == nil {
			continue
		}
		scope := pkg.Types.Scope()
		for _, name := range scope.Names() {
			obj := scope.Lookup(name)
			if !obj.Exported() {
				continue
			}
			if fn, ok := obj.(*types.Func); ok {
				checkFunc(pkg.Types.Path(), fn)
			} else if typeName, ok := obj.(*types.TypeName); ok {
				if named, ok := typeName.Type().(*types.Named); ok {
					for i := 0; i < named.NumMethods(); i++ {
						m := named.Method(i)
						if m.Exported() {
							checkMethod(pkg.Types.Path(), named.Obj().Name(), false, m)
						}
					}
					// pointer methods
					ptr := types.NewPointer(named)
					mset := types.NewMethodSet(ptr)
					for i := 0; i < mset.Len(); i++ {
						m := mset.At(i).Obj().(*types.Func)
						if m.Exported() {
							checkMethod(pkg.Types.Path(), named.Obj().Name(), true, m)
						}
					}
				}
			}
		}
	}
}

func checkFunc(pkgPath string, fn *types.Func) {
	sig, ok := fn.Type().(*types.Signature)
	if !ok {
		return
	}
	if returnsError(sig) {
		fmt.Printf("FUNC\t%s.%s\n", pkgPath, fn.Name())
	}
}

func checkMethod(pkgPath, recvName string, isPtr bool, m *types.Func) {
	sig, ok := m.Type().(*types.Signature)
	if !ok {
		return
	}
	if returnsError(sig) {
		ptrStr := ""
		if isPtr {
			ptrStr = "*"
		}
		fmt.Printf("METHOD\t(%s%s.%s).%s\n", ptrStr, pkgPath, recvName, m.Name())
	}
}

func returnsError(sig *types.Signature) bool {
	res := sig.Results()
	if res == nil {
		return false
	}
	for i := 0; i < res.Len(); i++ {
		if res.At(i).Type().String() == "error" {
			return true
		}
	}
	return false
}
EOF
go run /tmp/gen_stdlib_test.go | head -n 30
"}

