							sym, selName := getCallSymbol(pkg.TypesInfo, call)
							if !isExcluded(call, pkg.TypesInfo, sym, pkg.PkgPath, rules, ignorePkgMap, ignore) {
								p := pkg.Fset.Position(call.Pos())
								unchecked = append(unchecked, UncheckedError{
									Pos:          p,
									SelectorName: selName,
									LineText:     getLineText(pkg.Fset, stmt.Pos()),
								})
							}
						}
					}
				case *ast.DeferStmt:
					call := stmt.Call
					if call != nil {
						if hasErr, _ := returnsError(pkg.TypesInfo, call); hasErr {
							sym, selName := getCallSymbol(pkg.TypesInfo, call)
							if !isExcluded(call, pkg.TypesInfo, sym, pkg.PkgPath, rules, ignorePkgMap, ignore) {
								p := pkg.Fset.Position(call.Pos())
								unchecked = append(unchecked, UncheckedError{
									Pos:          p,
									SelectorName: selName,
									LineText:     getLineText(pkg.Fset, stmt.Pos()),
								})
							}
						}
					}
				case *ast.AssignStmt:
					if blank {
						if len(stmt.Rhs) == 1 {
							if call, ok := stmt.Rhs[0].(*ast.CallExpr); ok {
								if hasErr, errIdx := returnsError(pkg.TypesInfo, call); hasErr {
									if errIdx < len(stmt.Lhs) {
										if ident, ok := stmt.Lhs[errIdx].(*ast.Ident); ok && ident.Name == "_" {
											sym, selName := getCallSymbol(pkg.TypesInfo, call)
											if !isExcluded(call, pkg.TypesInfo, sym, pkg.PkgPath, rules, ignorePkgMap, ignore) {
												p := pkg.Fset.Position(ident.Pos())
												unchecked = append(unchecked, UncheckedError{
													Pos:          p,
													SelectorName: selName,
													LineText:     getLineText(pkg.Fset, stmt.Pos()),
												})
											}
										}
									}
								}
							}
						} else {
							for i, rhs := range stmt.Rhs {
								if call, ok := rhs.(*ast.CallExpr); ok {
									if hasErr, _ := returnsError(pkg.TypesInfo, call); hasErr {
										if i < len(stmt.Lhs) {
											if ident, ok := stmt.Lhs[i].(*ast.Ident); ok && ident.Name == "_" {
												sym, selName := getCallSymbol(pkg.TypesInfo, call)
												if !isExcluded(call, pkg.TypesInfo, sym, pkg.PkgPath, rules, ignorePkgMap, ignore) {
													p := pkg.Fset.Position(ident.Pos())
													unchecked = append(unchecked, UncheckedError{
														Pos:          p,
														SelectorName: selName,
														LineText:     getLineText(pkg.Fset, stmt.Pos()),
													})
												}
											}
										}
									}
								}
							}
						}
					}
					if asserts {
						if len(stmt.Rhs) == 1 {
							if typeAssert, ok := stmt.Rhs[0].(*ast.TypeAssertExpr); ok {
								if len(stmt.Lhs) == 2 && blank {
									if ident, ok := stmt.Lhs[1].(*ast.Ident); ok && ident.Name == "_" {
										p := pkg.Fset.Position(ident.Pos())
										unchecked = append(unchecked, UncheckedError{
											Pos:      p,
											LineText: getLineText(pkg.Fset, stmt.Pos()),
										})
									}
								}
							}
						}
					}
				case *ast.TypeAssertExpr:
					if asserts {
						p := pkg.Fset.Position(stmt.X.End())
						lineText := getLineText(pkg.Fset, stmt.Pos())
						unchecked = append(unchecked, UncheckedError{
							Pos:      p,
							LineText: lineText,
						})
					}
				}
