			})
		}
	}

	if len(unchecked) > 0 {
		sort.Slice(unchecked, func(i, j int) bool {
			if unchecked[i].Pos.Filename != unchecked[j].Pos.Filename {
				return unchecked[i].Pos.Filename < unchecked[j].Pos.Filename
			}
			if unchecked[i].Pos.Line != unchecked[j].Pos.Line {
				return unchecked[i].Pos.Line < unchecked[j].Pos.Line
			}
			return unchecked[i].Pos.Column < unchecked[j].Pos.Column
		})

		cwd, _ := os.Getwd()
		for _, item := range unchecked {
			filePath := item.Pos.Filename
			if abspath {
				if abs, err := filepath.Abs(filePath); err == nil {
					filePath = abs
				}
			} else {
				if rel, err := filepath.Rel(cwd, filePath); err == nil {
					filePath = rel
				}
			}

			if verbose && item.SelectorName != "" {
				fmt.Printf("%s:%d:%d:\t%s\t%s\n", filePath, item.Pos.Line, item.Pos.Column, item.SelectorName, item.LineText)
			} else {
				fmt.Printf("%s:%d:%d:\t%s\n", filePath, item.Pos.Line, item.Pos.Column, item.LineText)
			}
		}
		os.Exit(1)
	}

	os.Exit(0)
}
