var errorType = types.Universe.Lookup("error").Type().Underlying().(*types.Interface)

func isErrorType(t types.Type) (bool, int) {
	if t == nil {
		return false, -1
	}
	if tuple, ok := t.(*types.Tuple); ok {
		for i := 0; i < tuple.Len(); i++ {
			if types.Implements(tuple.At(i).Type(), errorType) {
				return true, i
			}
		}
		return false, -1
	}
	if types.Implements(t, errorType) {
		return true, 0
	}
	return false, -1
}

func returnsError(info *types.Info, call *ast.CallExpr) (bool, int) {
	tv, ok := info.Types[call]
	if !ok {
		return false, -1
	}
	return isErrorType(tv.Type)
