func isExcluded(call *ast.CallExpr, info *types.Info, symbol string, pkgPath string, rules []*ExcludeRule, ignorePkgMap map[string]bool, ignoreMap ignoreValue) bool {
	if ignorePkgMap[pkgPath] {
		return true
	}
	for p, re := range ignoreMap {
		if p == "" || p == pkgPath {
			funStr := ""
			if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
				funStr = sel.Sel.Name
			} else if ident, ok := call.Fun.(*ast.Ident); ok {
				funStr = ident.Name
			}
			if re.MatchString(funStr) || (symbol != "" && re.MatchString(symbol)) {
				return true
			}
		}
	}
	if symbol == "" {
		return false
	}
	for _, rule := range rules {
		if rule.Symbol == symbol {
			if rule.LiteralIdent != "" {
				if len(call.Args) > 0 {
					if argSel, ok := call.Args[0].(*ast.SelectorExpr); ok {
						if xIdent, ok1 := argSel.X.(*ast.Ident); ok1 {
							lit := xIdent.Name + "." + argSel.Sel.Name
							if lit == rule.LiteralIdent {
								return true
							}
						}
					}
				}
			} else if rule.ArgType != "" {
				if len(call.Args) > 0 {
					argType := info.TypeOf(call.Args[0])
					if argType != nil && argType.String() == rule.ArgType {
						return true
					}
				}
			} else {
				return true
			}
		}
	}
	return false
}

func getLineText(fset *token.FileSet, pos token.Pos) string {
	p := fset.Position(pos)
	if p.Filename == "" || p.Line <= 0 {
		return ""
	}
	f, err := os.Open(p.Filename)
	if err != nil {
		return ""
	}
	defer f.Close()

	scanner := bufio.NewScanner(f)
	currentLine := 0
	for scanner.Scan() {
		currentLine++
		if currentLine == p.Line {
			return strings.TrimSpace(scanner.Text())
		}
	}
	return ""
}

