}

var errorType = types.Universe.Lookup("error").Type().Underlying().(*types.Interface)

func isErrorType(t types.Type) (bool, int) {
	if t == nil {
		return false, -1
	}
	if tuple, ok := t.(*types.Tuple); ok {
		for i := 0; i < tuple.Len(); i++ {
			if types.Implements(tuple.At(i).Type(), errorType) {
				return true, i
			}
		}
		return false, -1
	}
	if types.Implements(t, errorType) {
		return true, 0
	}
	return false, -1
}

func returnsError(info *types.Info, call *ast.CallExpr) (bool, int) {
	tv, ok := info.Types[call]
	if !ok {
		return false, -1
	}
	return isErrorType(tv.Type)
}

func getCallInfo(info *types.Info, call *ast.CallExpr) (string, string, string) {
	fun := call.Fun
	for {
		if paren, ok := fun.(*ast.ParenExpr); ok {
			fun = paren.X
		} else {
			break
		}
	}

	if sel, ok := fun.(*ast.SelectorExpr); ok {
		if selection, ok := info.Selections[sel]; ok {
			obj := selection.Obj()
			recv := selection.Recv()
			var recvStr string
			if ptr, isPtr := recv.(*types.Pointer); isPtr {
				recvStr = "(*" + ptr.Elem().String() + ")"
			} else {
				recvStr = "(" + recv.String() + ")"
			}
			sym := recvStr + "." + obj.Name()
			callPkgPath := ""
			if obj.Pkg() != nil {
				callPkgPath = obj.Pkg().Path()
			}
			return callPkgPath, sym, sym
		} else if obj := info.ObjectOf(sel.Sel); obj != nil {
			callPkgPath := ""
			if obj.Pkg() != nil {
				callPkgPath = obj.Pkg().Path()
			}
			sym := sel.Sel.Name
			if callPkgPath != "" {
				sym = callPkgPath + "." + obj.Name()
			}
			return callPkgPath, sym, sym
		}
		return "", sel.Sel.Name, sel.Sel.Name
	} else if ident, ok := fun.(*ast.Ident); ok {
		obj := info.ObjectOf(ident)
		callPkgPath := ""
		sym := ident.Name
		if obj != nil && obj.Pkg() != nil {
			callPkgPath = obj.Pkg().Path()
			sym = callPkgPath + "." + obj.Name()
		}
		return callPkgPath, sym, ""
	}
	return "", "", ""
}

func isExcluded(call *ast.CallExpr, info *types.Info, symbol string, callPkgPath string, rules []*ExcludeRule, ignorePkgMap map[string]bool, ignoreMap ignoreValue) bool {
	if callPkgPath != "" && ignorePkgMap[callPkgPath] {
		return true
	}
	for p, re := range ignoreMap {
		if p == "" || p == callPkgPath {
			funStr := ""
			if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
				funStr = sel.Sel.Name
			} else if ident, ok := call.Fun.(*ast.Ident); ok {
				funStr = ident.Name
			}
			if re.MatchString(funStr) || (symbol != "" && re.MatchString(symbol)) {
				return true
			}
		}
	}
	if symbol == "" {
		return false
	}
	for _, rule := range rules {
		if rule.Symbol == symbol {
			if rule.LiteralIdent != "" {
				if len(call.Args) > 0 {
					if argSel, ok := call.Args[0].(*ast.SelectorExpr); ok {
						if xIdent, ok1 := argSel.X.(*ast.Ident); ok1 {
							lit := xIdent.Name + "." + argSel.Sel.Name
							if lit == rule.LiteralIdent {
								return true
							}
						}
					}
				}
			} else if rule.ArgType != "" {
				if len(call.Args) > 0 {
					argType := info.TypeOf(call.Args[0])
					if argType != nil && argType.String() == rule.ArgType {
						return true
					}
				}
			} else {
				return true
			}
		}
	}
	return false
}

func getLineText(fset *token.FileSet, pos token.Pos) string {
	p := fset.Position(pos)
	if p.Filename == "" || p.Line <= 0 {
		return ""
	}
	f, err := os.Open(p.Filename)
	if err != nil {
		return ""
	}
	defer f.Close()

	scanner := bufio.NewScanner(f)
	currentLine := 0
	for scanner.Scan() {
		currentLine++
		if currentLine == p.Line {
			return strings.TrimSpace(scanner.Text())
		}
	}
	return ""
}

func isTwoValueTypeAssert(assertExpr *ast.TypeAssertExpr, file *ast.File) (bool, *ast.AssignStmt) {
	var isTwoVal bool
	var parentAssign *ast.AssignStmt
	ast.Inspect(file, func(n ast.Node) bool {
		if assign, ok := n.(*ast.AssignStmt); ok {
			if len(assign.Lhs) == 2 && len(assign.Rhs) == 1 {
				if assign.Rhs[0] == assertExpr {
					isTwoVal = true
					parentAssign = assign
					return false
				}
			}
		}
		return true
	})
	return isTwoVal, parentAssign
}

func main() {
	var (
		abspath         bool
		asserts         bool
		blank           bool
		excludePath     string
		excludeonly     bool
		ignore          ignoreValue = make(ignoreValue)
		ignoregenerated bool
		ignorepkg       string
		ignoretests     bool
		mod             string
		tags            tagsValue
		verbose         bool
	)

	flags := flag.NewFlagSet(os.Args[0], flag.ExitOnError)
	flags.BoolVar(&abspath, "abspath", false, "print absolute paths to files")
	flags.BoolVar(&asserts, "asserts", false, "if true, check for ignored type assertion results")
	flags.BoolVar(&blank, "blank", false, "if true, check for errors assigned to blank identifier")
	flags.StringVar(&excludePath, "exclude", "", "Path to a file containing a list of functions to exclude from checking")
	flags.BoolVar(&excludeonly, "excludeonly", false, "Use only excludes from -exclude file")
	flags.Var(&ignore, "ignore", "[deprecated] comma-separated list of pairs of the form pkg:regex\n            the regex is used to ignore names within pkg.")
	flags.BoolVar(&ignoregenerated, "ignoregenerated", false, "if true, checking of files with generated code is disabled")
	flags.StringVar(&ignorepkg, "ignorepkg", "", "comma-separated list of package paths to ignore")
	flags.BoolVar(&ignoretests, "ignoretests", false, "if true, checking of _test.go files is disabled")
	flags.StringVar(&mod, "mod", "", "module download mode to use: readonly or vendor. See 'go help modules' for more.")
	flags.Var(&tags, "tags", "comma or space-separated list of build tags to include")
	flags.BoolVar(&verbose, "verbose", false, "produce more verbose logging")

	if err := flags.Parse(os.Args[1:]); err != nil {
		os.Exit(2)
	}

	var rules []*ExcludeRule
	if !excludeonly {
		for _, line := range DefaultExcludes {
			if r := parseExcludeLine(line); r != nil {
				rules = append(rules, r)
			}
		}
	}
	if excludePath != "" {
		f, err := os.Open(excludePath)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: %v\n", err)
			os.Exit(2)
		}
		scanner := bufio.NewScanner(f)
		for scanner.Scan() {
			if r := parseExcludeLine(scanner.Text()); r != nil {
				rules = append(rules, r)
			}
		}
		f.Close()
	}

	ignorePkgMap := make(map[string]bool)
	if ignorepkg != "" {
		for _, p := range strings.Split(ignorepkg, ",") {
			p = strings.TrimSpace(p)
			if p != "" {
				ignorePkgMap[p] = true
			}
		}
	}

	args := flags.Args()
	if len(args) == 0 {
		args = []string{"."}
	}

	cfg := &packages.Config{
		Mode:  packages.NeedName | packages.NeedFiles | packages.NeedCompiledGoFiles | packages.NeedImports | packages.NeedTypes | packages.NeedTypesInfo | packages.NeedSyntax,
		Tests: !ignoretests,
	}

	var buildFlags []string
	if len(tags) > 0 {
		buildFlags = append(buildFlags, "-tags", strings.Join(tags, " "))
	}
	if mod != "" {
		buildFlags = append(buildFlags, "-mod="+mod)
	}
	if len(buildFlags) > 0 {
		cfg.BuildFlags = buildFlags
	}

	pkgs, err := packages.Load(cfg, args...)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: failed to check packages: %v\n", err)
		os.Exit(2)
	}

	hasPkgErrors := false
	for _, pkg := range pkgs {
		if len(pkg.Errors) > 0 {
			hasPkgErrors = true
			fmt.Fprintf(os.Stderr, "error: failed to check packages: errors while loading package %s: %v\n", pkg.ID, pkg.Errors)
		}
	}
	if hasPkgErrors {
		os.Exit(2)
	}

	var unchecked []UncheckedError

	for _, pkg := range pkgs {
		if verbose {
			fmt.Fprintf(os.Stderr, "checking %s\n", pkg.ID)
		}

		for _, file := range pkg.Syntax {
			pos := pkg.Fset.Position(file.Package)
			filename := pos.Filename
			if filename == "" {
				continue
			}

			if ignoretests && strings.HasSuffix(filename, "_test.go") {
				continue
			}
			if ignoregenerated && isGeneratedFile(file) {
				continue
			}

			ast.Inspect(file, func(node ast.Node) bool {
				if node == nil {
					return true
				}

				switch stmt := node.(type) {
				case *ast.ExprStmt:
					if call, ok := stmt.X.(*ast.CallExpr); ok {
						if hasErr, _ := returnsError(pkg.TypesInfo, call); hasErr {
							callPkg, sym, selName := getCallInfo(pkg.TypesInfo, call)
							if !isExcluded(call, pkg.TypesInfo, sym, callPkg, rules, ignorePkgMap, ignore) {
								p := pkg.Fset.Position(call.Pos())
								unchecked = append(unchecked, UncheckedError{
									Pos:          p,
									SelectorName: selName,
									LineText:     getLineText(pkg.Fset, call.Pos()),
								})
							}
						}
					}
				case *ast.GoStmt:
					call := stmt.Call
					if call != nil {
						if hasErr, _ := returnsError(pkg.TypesInfo, call); hasErr {
							callPkg, sym, selName := getCallInfo(pkg.TypesInfo, call)
							if !isExcluded(call, pkg.TypesInfo, sym, callPkg, rules, ignorePkgMap, ignore) {
								p := pkg.Fset.Position(call.Pos())
								unchecked = append(unchecked, UncheckedError{
									Pos:          p,
									SelectorName: selName,
									LineText:     getLineText(pkg.Fset, stmt.Pos()),
								})
							}
						}
					}
				case *ast.DeferStmt:
					call := stmt.Call
					if call != nil {
						if hasErr, _ := returnsError(pkg.TypesInfo, call); hasErr {
							callPkg, sym, selName := getCallInfo(pkg.TypesInfo, call)
							if !isExcluded(call, pkg.TypesInfo, sym, callPkg, rules, ignorePkgMap, ignore) {
								p := pkg.Fset.Position(call.Pos())
								unchecked = append(unchecked, UncheckedError{
									Pos:          p,
									SelectorName: selName,
									LineText:     getLineText(pkg.Fset, stmt.Pos()),
								})
							}
						}
					}
				case *ast.AssignStmt:
					if len(stmt.Rhs) == 1 {
						if call, ok := stmt.Rhs[0].(*ast.CallExpr); ok {
							if hasErr, errIdx := returnsError(pkg.TypesInfo, call); hasErr {
								if blank && errIdx < len(stmt.Lhs) {
									if ident, ok := stmt.Lhs[errIdx].(*ast.Ident); ok && ident.Name == "_" {
										callPkg, sym, selName := getCallInfo(pkg.TypesInfo, call)
										if !isExcluded(call, pkg.TypesInfo, sym, callPkg, rules, ignorePkgMap, ignore) {
											p := pkg.Fset.Position(ident.Pos())
											unchecked = append(unchecked, UncheckedError{
												Pos:          p,
												SelectorName: selName,
												LineText:     getLineText(pkg.Fset, stmt.Pos()),
											})
										}
									}
								}
							}
						}
					} else {
						for i, rhs := range stmt.Rhs {
							if call, ok := rhs.(*ast.CallExpr); ok {
								if hasErr, _ := returnsError(pkg.TypesInfo, call); hasErr {
									if blank && i < len(stmt.Lhs) {
										if ident, ok := stmt.Lhs[i].(*ast.Ident); ok && ident.Name == "_" {
											callPkg, sym, selName := getCallInfo(pkg.TypesInfo, call)
											if !isExcluded(call, pkg.TypesInfo, sym, callPkg, rules, ignorePkgMap, ignore) {
												p := pkg.Fset.Position(ident.Pos())
												unchecked = append(unchecked, UncheckedError{
													Pos:          p,
													SelectorName: selName,
													LineText:     getLineText(pkg.Fset, stmt.Pos()),
												})
											}
										}
									}
								}
							}
						}
					}
				case *ast.TypeAssertExpr:
					isTwoVal, parentAssign := isTwoValueTypeAssert(stmt, file)
					if isTwoVal {
						if blank && asserts {
							if ident, ok := parentAssign.Lhs[1].(*ast.Ident); ok && ident.Name == "_" {
								p := pkg.Fset.Position(ident.Pos())
								unchecked = append(unchecked, UncheckedError{
									Pos:      p,
									LineText: getLineText(pkg.Fset, parentAssign.Pos()),
								})
							}
						}
					} else {
						if asserts {
							p := pkg.Fset.Position(stmt.X.End())
							unchecked = append(unchecked, UncheckedError{
								Pos:      p,
								LineText: getLineText(pkg.Fset, stmt.Pos()),
							})
						}
					}
				}
				return true
			})
		}
	}

	if len(unchecked) > 0 {
		seen := make(map[string]bool)
		var unique []UncheckedError
		for _, item := range unchecked {
			key := fmt.Sprintf("%s:%d:%d", item.Pos.Filename, item.Pos.Line, item.Pos.Column)
			if !seen[key] {
				seen[key] = true
				unique = append(unique, item)
			}
		}
		unchecked = unique

		sort.Slice(unchecked, func(i, j int) bool {
			if unchecked[i].Pos.Filename != unchecked[j].Pos.Filename {
				return unchecked[i].Pos.Filename < unchecked[j].Pos.Filename
			}
			if unchecked[i].Pos.Line != unchecked[j].Pos.Line {
				return unchecked[i].Pos.Line < unchecked[j].Pos.Line
			}
			return unchecked[i].Pos.Column < unchecked[j].Pos.Column
		})

		cwd, _ := os.Getwd()
		for _, item := range unchecked {
			filePath := item.Pos.Filename
			if abspath {
				if abs, err := filepath.Abs(filePath); err == nil {
					filePath = abs
				}
			} else {
				if rel, err := filepath.Rel(cwd, filePath); err == nil {
					filePath = rel
				}
			}

			if verbose && item.SelectorName != "" {
				fmt.Printf("%s:%d:%d:\t%s\t%s\n", filePath, item.Pos.Line, item.Pos.Column, item.SelectorName, item.LineText)
			} else {
				fmt.Printf("%s:%d:%d:\t%s\n", filePath, item.Pos.Line, item.Pos.Column, item.LineText)
			}
		}
		os.Exit(1)
	}

	os.Exit(0)
}
EOF"}

