type tagsValue []string

func (t *tagsValue) String() string {
	return strings.Join(*t, " ")
}

func (t *tagsValue) Set(val string) error {
	fields := strings.FieldsFunc(val, func(r rune) bool {
		return r == ' ' || r == ','
	})
	*t = append(*t, fields...)
	return nil
}

type ignoreValue map[string]*regexp.Regexp

func (i *ignoreValue) String() string {
	return ""
}

func (i *ignoreValue) Set(val string) error {
	if *i == nil {
		*i = make(map[string]*regexp.Regexp)
	}
	pairs := strings.Split(val, ",")
	for _, pair := range pairs {
		pair = strings.TrimSpace(pair)
		if pair == "" {
			continue
		}
		parts := strings.SplitN(pair, ":", 2)
		var pkg, reStr string
		if len(parts) == 2 {
			pkg = parts[0]
			reStr = parts[1]
		} else {
			reStr = parts[0]
		}
		re, err := regexp.Compile(reStr)
		if err != nil {
			return err
		}
		(*i)[pkg] = re
	}
	return nil
}

type ExcludeRule struct {
	Symbol       string
	ArgType      string
	LiteralIdent string
}

func parseExcludeLine(line string) *ExcludeRule {
	line = strings.TrimSpace(line)
	if line == "" || strings.HasPrefix(line, "//") {
		return nil
	}
	rule := &ExcludeRule{}
	if idx := strings.LastIndex(line, "("); idx != -1 && strings.HasSuffix(line, ")") {
		rule.Symbol = strings.TrimSpace(line[:idx])
		inner := strings.TrimSpace(line[idx+1 : len(line)-1])
		if inner == "os.Stdout" || inner == "os.Stderr" {
			rule.LiteralIdent = inner
		} else {
			rule.ArgType = inner
		}
	} else {
		rule.Symbol = line
	}
	return rule
}

var DefaultExcludes = []string{
	"(*bytes.Buffer).Write",
	"(*bytes.Buffer).WriteByte",
	"(*bytes.Buffer).WriteRune",
	"(*bytes.Buffer).WriteString",
	"(*strings.Builder).Write",
	"(*strings.Builder).WriteByte",
	"(*strings.Builder).WriteRune",
	"(*strings.Builder).WriteString",
	"fmt.Print",
	"fmt.Printf",
	"fmt.Println",
	"fmt.Fprint(os.Stderr)",
	"fmt.Fprintf(os.Stderr)",
	"fmt.Fprintln(os.Stderr)",
	"math/rand.Read",
	"(*math/rand.Rand).Read",
	"(hash.Hash).Write",
}

type UncheckedError struct {
	Pos          token.Position
	SelectorName string
	LineText     string
}

var regexGenerated = regexp.MustCompile(`^// Code generated .* DO NOT EDIT\.$`)

func isGeneratedFile(file *ast.File) bool {
	for _, cg := range file.Comments {
		for _, c := range cg.List {
			if regexGenerated.MatchString(strings.TrimSpace(c.Text)) {
				return true
			}
		}
	}
	return false
}

var errorType = types.Universe.Lookup("error").Type().Underlying().(*types.Interface)

func isErrorType(t types.Type) (bool, int) {
	if t == nil {
		return false, -1
	}
	if tuple, ok := t.(*types.Tuple); ok {
		for i := 0; i < tuple.Len(); i++ {
			if types.Implements(tuple.At(i).Type(), errorType) {
				return true, i
			}
		}
		return false, -1
	}
	if types.Implements(t, errorType) {
		return true, 0
	}
	return false, -1
}

func returnsError(info *types.Info, call *ast.CallExpr) (bool, int) {
	tv, ok := info.Types[call]
	if !ok {
		return false, -1
	}
	return isErrorType(tv.Type)
}

func getCallInfo(info *types.Info, call *ast.CallExpr) (string, string, string) {
	fun := call.Fun
	for {
		if paren, ok := fun.(*ast.ParenExpr); ok {
			fun = paren.X
		} else {
			break
		}
	}

	if sel, ok := fun.(*ast.SelectorExpr); ok {
		if selection, ok := info.Selections[sel]; ok {
			obj := selection.Obj()
			recv := selection.Recv()
			var recvStr string
			if ptr, isPtr := recv.(*types.Pointer); isPtr {
				recvStr = "(*" + ptr.Elem().String() + ")"
			} else {
				recvStr = "(" + recv.String() + ")"
			}
			sym := recvStr + "." + obj.Name()
			callPkgPath := ""
			if obj.Pkg() != nil {
				callPkgPath = obj.Pkg().Path()
			}
			return callPkgPath, sym, sym
		} else if obj := info.ObjectOf(sel.Sel); obj != nil {
			callPkgPath := ""
			if obj.Pkg() != nil {
				callPkgPath = obj.Pkg().Path()
			}
			sym := sel.Sel.Name
			if callPkgPath != "" {
				sym = callPkgPath + "." + obj.Name()
			}
			return callPkgPath, sym, sym
		}
		return "", sel.Sel.Name, sel.Sel.Name
	} else if ident, ok := fun.(*ast.Ident); ok {
		obj := info.ObjectOf(ident)
		callPkgPath := ""
		sym := ident.Name
		if obj != nil && obj.Pkg() != nil {
			callPkgPath = obj.Pkg().Path()
			sym = callPkgPath + "." + obj.Name()
		}
		return callPkgPath, sym, ""
	}
	return "", "", ""
}

func isExcluded(call *ast.CallExpr, info *types.Info, symbol string, callPkgPath string, rules []*ExcludeRule, ignorePkgMap map[string]bool, ignoreMap ignoreValue) bool {
	if callPkgPath != "" && ignorePkgMap[callPkgPath] {
		return true
	}
	for p, re := range ignoreMap {
		if p == "" || p == callPkgPath {
			funStr := ""
			if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
				funStr = sel.Sel.Name
			} else if ident, ok := call.Fun.(*ast.Ident); ok {
				funStr = ident.Name
			}
			if re.MatchString(funStr) || (symbol != "" && re.MatchString(symbol)) {
				return true
			}
		}
	}
	if symbol == "" {
		return false
	}
	for _, rule := range rules {
		if rule.Symbol == symbol {
			if rule.LiteralIdent != "" {
				if len(call.Args) > 0 {
					if argSel, ok := call.Args[0].(*ast.SelectorExpr); ok {
						if xIdent, ok1 := argSel.X.(*ast.Ident); ok1 {
							lit := xIdent.Name + "." + argSel.Sel.Name
							if lit == rule.LiteralIdent {
								return true
							}
						}
					}
				}
			} else if rule.ArgType != "" {
				if len(call.Args) > 0 {
					argType := info.TypeOf(call.Args[0])
					if argType != nil && argType.String() == rule.ArgType {
						return true
					}
				}
			} else {
				return true
			}
		}
	}
	return false
}

func getLineText(fset *token.FileSet, pos token.Pos) string {
