		currentLine++
		if currentLine == p.Line {
			return strings.TrimSpace(scanner.Text())
		}
	}
	return ""
}

func isTwoValueTypeAssert(assertExpr *ast.TypeAssertExpr, file *ast.File) (bool, *ast.AssignStmt) {
	var isTwoVal bool
	var parentAssign *ast.AssignStmt
	ast.Inspect(file, func(n ast.Node) bool {
		if assign, ok := n.(*ast.AssignStmt); ok {
			if len(assign.Lhs) == 2 && len(assign.Rhs) == 1 {
				if assign.Rhs[0] == assertExpr {
					isTwoVal = true
					parentAssign = assign
					return false
				}
			}
		}
		return true
	})
	return isTwoVal, parentAssign
}

func main() {
	var (
